/**
 * Gran Turismo 7 track catalogue: the official 122 layouts (id, English name, length, corners,
 * elevation, longest straight, country, oval/reverse/fictional) and the pure helpers the UI and the
 * server need: lookup by id/name, search without accents, and the length window used to suggest a
 * layout for a lap the app measured.
 *
 * Data: ./data.ts (generated by scripts/gen-tracks.mjs; sources and licences in TRACKS_SOURCES).
 * The telemetry packet carries no track id, so none of this is "read from the game": it is the
 * list we compare our own measurements against (see ./match.ts for the geometric recognition).
 */

import { DGEDGE_PATHS, TRACK_LAYOUTS_DATA } from './data.ts';

export interface TrackLayout {
  /** Official (hex) id of the layout, unique and stable. */
  id: string;
  /** gt7info numeric course id when known (`null`: shared row or not published yet). */
  courseId: number | null;
  /** The numeric id is a placeholder in gt7info (Eiger, Yas Marina, Gilles-Villeneuve). */
  courseIdDummy: boolean;
  /** Circuit / location as the game groups it ("Nürburgring", "Autodromo Nazionale Monza"). */
  venue: string;
  /** Layout name as in the official list ("Full Course", "No Chicane"). */
  layout: string;
  /** Full official name ("Trial Mountain Circuit (Reverse)"). */
  officialName: string;
  /**
   * Layout label to show next to the venue; `null` when the venue has a single forward layout
   * ("Full Course" is not repeated). Reverse layouts end with "(Reverse)".
   */
  layoutLabel: string | null;
  /** "Venue – Layout" as shown to the user. */
  displayName: string;
  /** ISO-like country code of the source ("jp", "us", "gb"…). */
  country: string;
  /** Country name in pt-BR. */
  countryName: string;
  /** Official lap length (m). */
  lengthM: number;
  /** Official corner count. */
  turns: number;
  /** Elevation difference (m). */
  elevationM: number;
  /** Longest straight (m); `null` when the sources do not list it. */
  longestStraightM: number | null;
  oval: boolean;
  reverse: boolean;
  /** Fictional (Polyphony-original) circuit; `false` = real-world circuit. */
  fictional: boolean;
  /** Start/finish point in the game's X/Z, when known. */
  start: { x: number; z: number } | null;
  /** Forward layout this one is the reverse of. */
  reverseOf: string | null;
}

const COUNTRY_NAMES_PT: Record<string, string> = {
  jp: 'Japão',
  us: 'Estados Unidos',
  gb: 'Reino Unido',
  de: 'Alemanha',
  fr: 'França',
  it: 'Itália',
  au: 'Austrália',
  kr: 'Coreia do Sul',
  be: 'Bélgica',
  se: 'Suécia',
  es: 'Espanha',
  ca: 'Canadá',
  at: 'Áustria',
  ch: 'Suíça',
  br: 'Brasil',
  hr: 'Croácia',
  cz: 'Tchéquia',
  cn: 'China',
  ae: 'Emirados Árabes Unidos',
  pdi: 'Outros',
};

/** Lowercase, no accents, punctuation to spaces. */
export function normalizeTrackText(s: string): string {
  return s
    .normalize('NFD')
    .replace(/[̀-ͯ]/g, '')
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, ' ')
    .trim();
}

function build(): TrackLayout[] {
  const forwardCount = new Map<string, number>();
  for (const r of TRACK_LAYOUTS_DATA) {
    if ((r[10] & 2) === 0) forwardCount.set(r[2], (forwardCount.get(r[2]) ?? 0) + 1);
  }
  const labelOf = (venue: string, layout: string): string | null =>
    layout === 'Full Course' && forwardCount.get(venue) === 1 ? null : layout;

  return TRACK_LAYOUTS_DATA.map((r): TrackLayout => {
    const [id, courseId, venue, layout, officialName, country, lengthM, turns, elevationM] = r;
    const flags = r[10];
    const reverse = (flags & 2) !== 0;
    const base = labelOf(venue, layout);
    const layoutLabel = reverse ? (base ? `${base} (Reverse)` : 'Reverse') : base;
    return {
      id,
      courseId,
      courseIdDummy: (flags & 8) !== 0,
      venue,
      layout,
      officialName,
      layoutLabel,
      displayName: layoutLabel ? `${venue} – ${layoutLabel}` : venue,
      country,
      countryName: COUNTRY_NAMES_PT[country] ?? country.toUpperCase(),
      lengthM,
      turns,
      elevationM,
      longestStraightM: r[9],
      oval: (flags & 1) !== 0,
      reverse,
      fictional: (flags & 4) !== 0,
      start: r[11] !== null && r[12] !== null ? { x: r[11], z: r[12] } : null,
      reverseOf: r[13],
    };
  });
}

const LAYOUTS: readonly TrackLayout[] = build();
const BY_ID = new Map(LAYOUTS.map((l) => [l.id, l]));
const BY_COURSE_ID = new Map(
  LAYOUTS.filter((l) => l.courseId !== null && !l.courseIdDummy).map((l) => [l.courseId!, l]),
);
const BY_DISPLAY = new Map(LAYOUTS.map((l) => [normalizeTrackText(l.displayName), l]));
const SEARCH_TEXT = new Map(
  LAYOUTS.map((l) => [
    l.id,
    normalizeTrackText(`${l.displayName} ${l.officialName} ${l.layout} ${l.venue}`),
  ]),
);

export function listTrackLayouts(): readonly TrackLayout[] {
  return LAYOUTS;
}

export function getTrackLayout(id: string | null | undefined): TrackLayout | undefined {
  return id ? BY_ID.get(id) : undefined;
}

/** By gt7info numeric id (dummy ids are ignored: they do not identify anything in the game). */
export function findTrackLayoutByCourseId(courseId: number): TrackLayout | undefined {
  return BY_COURSE_ID.get(courseId);
}

/** Layouts of one venue (case/accent-insensitive), forward ones first. */
export function layoutsOfVenue(venue: string): TrackLayout[] {
  const v = normalizeTrackText(venue);
  return LAYOUTS.filter((l) => normalizeTrackText(l.venue) === v).sort(
    (a, b) => Number(a.reverse) - Number(b.reverse) || a.lengthM - b.lengthM,
  );
}

// ---------------------------------------------------------------------------------------------
// Length matching
// ---------------------------------------------------------------------------------------------

/**
 * The lap length the app measures (driven line) is shorter than the official one (measured along
 * the road axis): over the 81 layouts with a published driving line the ratio measured/official
 * has median 0.9905, p10 0.972, p90 1.0003. Window of relative error `(measured − official) /
 * official` accepted for a suggestion.
 */
export const LENGTH_WINDOW = { minRel: -0.04, maxRel: 0.015 } as const;
/** Typical relative error of the driven line (median of the survey above). */
export const LENGTH_TYPICAL_REL = -0.0095;

/** `(measured − official) / official`. */
export function lengthErrorRel(measuredM: number, officialM: number): number {
  return (measuredM - officialM) / officialM;
}

/** Is the measured length compatible with the official one (asymmetric window)? */
export function lengthCompatible(
  measuredM: number,
  officialM: number,
  window: { minRel: number; maxRel: number } = LENGTH_WINDOW,
): boolean {
  if (!(measuredM > 0) || !(officialM > 0)) return false;
  const e = lengthErrorRel(measuredM, officialM);
  // epsilon: 0.96 × 5434 must sit exactly on the edge
  return e >= window.minRel - 1e-9 && e <= window.maxRel + 1e-9;
}

export interface LengthCandidate {
  layout: TrackLayout;
  /** `(measured − official) / official`. */
  errorRel: number;
}

/**
 * Layouts whose official length is compatible with the measured one, ordered by how far the error
 * is from the typical −0.95 % (not from 0): a lap measured 1 % short is a better fit than one
 * measured 1 % long. Reverse layouts have the same length as their forward layout: both are
 * returned (the caller decides with the geometry, or asks the user).
 */
export function suggestLayoutsByLength(
  measuredM: number,
  opts: {
    window?: { minRel: number; maxRel: number };
    max?: number;
    catalog?: readonly TrackLayout[];
  } = {},
): LengthCandidate[] {
  if (!Number.isFinite(measuredM) || measuredM <= 0) return [];
  const window = opts.window ?? LENGTH_WINDOW;
  return (opts.catalog ?? LAYOUTS)
    .map((layout) => ({ layout, errorRel: lengthErrorRel(measuredM, layout.lengthM) }))
    .filter((c) => lengthCompatible(measuredM, c.layout.lengthM, window))
    .sort(
      (a, b) =>
        Math.abs(a.errorRel - LENGTH_TYPICAL_REL) - Math.abs(b.errorRel - LENGTH_TYPICAL_REL) ||
        Number(a.layout.reverse) - Number(b.layout.reverse),
    )
    .slice(0, opts.max ?? 3);
}

/**
 * Candidates that length alone cannot tell apart: the reverse of the best one, and layouts of the
 * same venue within 1.5 % of its length (Tokyo CW/CCW, Monza with/without chicane, Nordschleife and
 * Tourist, Fuji and Fuji Short…). The UI must ask for confirmation when this is not empty.
 */
export function lookAlikes(layout: TrackLayout, catalog = LAYOUTS): TrackLayout[] {
  return catalog.filter(
    (o) =>
      o.id !== layout.id &&
      o.venue === layout.venue &&
      Math.abs(o.lengthM - layout.lengthM) / layout.lengthM <= 0.015,
  );
}

// ---------------------------------------------------------------------------------------------
// Search / lookup by name
// ---------------------------------------------------------------------------------------------

/**
 * Autocomplete: every word typed must appear in "venue layout official name" (no accents, any
 * case). Entries whose display name starts with the text rank first, then the closest length when
 * `lengthM` is given, then the shorter layouts.
 */
export function searchTrackLayouts(
  query: string,
  lengthM?: number,
  max = 8,
  catalog: readonly TrackLayout[] = LAYOUTS,
): TrackLayout[] {
  const words = normalizeTrackText(query).split(' ').filter(Boolean);
  return catalog
    .filter((l) => {
      const text = SEARCH_TEXT.get(l.id) ?? normalizeTrackText(l.displayName);
      return words.every((w) => text.includes(w));
    })
    .map((l) => {
      const display = normalizeTrackText(l.displayName);
      const starts = words.length > 0 && display.startsWith(words[0]!) ? 0 : 1;
      const dist = lengthM ? Math.abs(lengthM - l.lengthM) / l.lengthM : 0;
      return { l, starts, dist };
    })
    .sort((a, b) => a.starts - b.starts || a.dist - b.dist || a.l.lengthM - b.l.lengthM)
    .slice(0, max)
    .map((x) => x.l);
}

/**
 * Finds the catalogue layout of a stored track (name + optional layout, as saved by the UI or typed
 * by the user). Exact display name first; then the venue plus the layout label; then, when a venue
 * matches but the layout does not (names saved by older versions, free text), the layout of that
 * venue closest in length within the length window. Returns `undefined` rather than guessing.
 */
export function findTrackLayout(
  name: string,
  layout?: string | null,
  lengthM?: number,
): TrackLayout | undefined {
  const full = normalizeTrackText(layout ? `${name} – ${layout}` : name);
  const hit = BY_DISPLAY.get(full);
  if (hit) return hit;
  const nName = normalizeTrackText(name);
  const nLayout = layout ? normalizeTrackText(layout) : '';
  const byOfficial = LAYOUTS.find((l) => normalizeTrackText(l.officialName) === nName);
  if (byOfficial && !layout) return byOfficial;
  const venue = LAYOUTS.filter((l) => normalizeTrackText(l.venue) === nName);
  if (venue.length === 0) return undefined;
  if (nLayout) {
    const exact = venue.find(
      (l) => normalizeTrackText(l.layoutLabel ?? l.layout) === nLayout && !l.reverse,
    );
    if (exact) return exact;
  }
  if (lengthM) {
    const near = suggestLayoutsByLength(lengthM, {
      catalog: venue.filter((l) => !l.reverse),
      max: 1,
    });
    if (near[0]) return near[0].layout;
  }
  return venue.length === 1 ? venue[0] : undefined;
}

// ---------------------------------------------------------------------------------------------
// External links (we link, we never copy their content)
// ---------------------------------------------------------------------------------------------

export interface TrackLink {
  label: string;
  url: string;
}

export const OFFICIAL_TRACKLIST_URL = 'https://www.gran-turismo.com/gb/gt7/tracklist/';
export const DGEDGE_TRACKS_URL = 'https://www.dg-edge.com/database/tracks';

export function trackLinks(layout: TrackLayout): TrackLink[] {
  const dg = DGEDGE_PATHS[layout.venue];
  return [
    { label: 'Lista oficial de pistas (Gran Turismo)', url: OFFICIAL_TRACKLIST_URL },
    {
      label: dg ? 'Pista no DG EDGE' : 'Banco de pistas do DG EDGE',
      url: dg ? `https://www.dg-edge.com/${dg}` : DGEDGE_TRACKS_URL,
    },
  ];
}
